def merge(intervals):
    """Merge overlapping or touching closed intervals; return sorted disjoint list."""
    out = []
    for s, e in sorted(intervals, key=lambda p: p[1]):
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out

